/** Production fade rewrite + real WBOIT equations; no game, attach or source-object mutation. */
public final class Fade122GpuProbe {
 static final int W=32;static int checks,cases,vao,fbo,depth,sum,reveal,distance,opaque,picks;static String fade,oit,range;
 static void require(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception {
  Path root=Path.of(args.length==0?"research/fade122-shaders/installed/viewpoint/shaders":args[0]);fade=Files.readString(root.resolve("lib/fade.glsl"));oit=Files.readString(root.resolve("lib/translucent.glsl"));
  range=NativeObjectShaders.rewrite("lib/sample_sprite.glsl","uniform vec2 uAlphaRange = vec2(0.3, 2.0);\n");
  require(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,5);long window=GLFW.glfwCreateWindow(W,W,"fade122 uniform alpha",0,0);require(window!=0,"hidden GL");
  try {GLFW.glfwMakeContextCurrent(window);GL.createCapabilities();vao=GL30.glGenVertexArrays();GL30.glBindVertexArray(vao);setup();int mesh=program(fragment("forward.frag")),model=program(fragment("model_glass.frag")),gbuffer=program(fragment("gbuffer.frag"));
   for(int p:new int[]{mesh,model})for(float alpha:new float[]{0,.25f,.5f,.75f,1})for(float geometry:new float[]{1,.5f})for(boolean hole:new boolean[]{false,true}) {
    begin();settings(gbuffer,alpha,geometry,hole,0,false);GL11.glDepthMask(true);GL11.glEnable(GL11.GL_DEPTH_TEST);GL11.glDepthFunc(GL11.GL_LESS);GL11.glDisable(GL11.GL_BLEND);GL20.glDrawBuffers(new int[]{0,0,0,GL30.GL_COLOR_ATTACHMENT3});GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);
    GL20.glDrawBuffers(new int[]{GL30.GL_COLOR_ATTACHMENT0,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_COLOR_ATTACHMENT2});GL11.glDepthMask(false);GL11.glEnable(GL11.GL_BLEND);GL40.glBlendFunci(0,GL11.GL_ONE,GL11.GL_ONE);GL40.glBlendFunci(1,GL11.GL_ZERO,GL11.GL_ONE_MINUS_SRC_COLOR);GL40.glBlendFunci(2,GL11.GL_ONE,GL11.GL_ONE);settings(p,alpha,geometry,hole,0,false);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);
    FloatBuffer sums=read(0,4),reveals=read(1,1),op=read(3,4);float coverage=alpha*geometry;
    for(int y=0;y<W;y++)for(int x=0;x<W;x++){int pixel=y*W+x;boolean cut=hole&&x<W/2;float expected=cut?0:coverage;float got=op.get(pixel*4)>.5?1:1-reveals.get(pixel);require(Math.abs(got-expected)<.0001,"uniform alpha p="+p+" a="+alpha+" geom="+geometry+" hole="+hole+" at="+x+","+y+" got="+got);if(expected>0&&expected<1){require(Math.abs(sums.get(pixel*4)/sums.get(pixel*4+3)-.3)<.0001,"layered tint/material lost");} }
    cases++;
   }
   for(float[] interval:new float[][]{{0,.4f},{.4f,2},{-1,.4f},{-.5f,2},{1.2f,2},{-.5f,-.1f},{.8f,.2f}}){begin();GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDepthMask(false);GL20.glDrawBuffers(new int[]{GL30.GL_COLOR_ATTACHMENT0,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_COLOR_ATTACHMENT2});GL11.glEnable(GL11.GL_BLEND);settings(mesh,.5f,1,false,0,false);GL20.glUniform2f(GL20.glGetUniformLocation(mesh,"interval"),interval[0],interval[1]);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer result=read(1,1);float expected=.5f*Math.max(0,Math.min(1,Math.max(0,interval[1]))-Math.min(1,Math.max(0,interval[0])));for(int i=0;i<W*W;i++)require(Math.abs((1-result.get(i))-expected)<.0001,"clipped fade interval "+Arrays.toString(interval));cases++;}
   for(int debug:new int[]{1,2}){begin();GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDepthMask(false);GL20.glDrawBuffers(new int[]{GL30.GL_COLOR_ATTACHMENT0,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_COLOR_ATTACHMENT2});GL11.glEnable(GL11.GL_BLEND);settings(mesh,.25f,1,false,0,false);GL20.glUniform1i(GL20.glGetUniformLocation(mesh,"uDebugView"),debug);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer result=read(1,1);for(int i=0;i<W*W;i++)require(Math.abs(1-result.get(i)-.25f)<.0001,"debug fade bypass "+debug);cases++;}
   // Opaque source + geometry fade routes to WBOIT; foreground depth still excludes it.
   for(float[] interval:new float[][]{{0,.5f},{.5f,2}}){begin();GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDisable(GL11.GL_BLEND);GL20.glDrawBuffers(new int[]{0,0,0,GL30.GL_COLOR_ATTACHMENT3});settings(gbuffer,1,1,false,0,false);GL20.glUniform1i(GL20.glGetUniformLocation(gbuffer,"testFlags"),64);GL20.glUniform2f(GL20.glGetUniformLocation(gbuffer,"interval"),interval[0],interval[1]);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer result=read(3,4);int visible=0;for(int i=0;i<W*W;i++)if(result.get(i*4)>0)visible++;require(visible>450&&visible<575,"baked-floor LOD disappeared "+Arrays.toString(interval)+" "+visible);cases++;}
   begin();GL11.glEnable(GL11.GL_DEPTH_TEST);GL11.glDepthFunc(GL11.GL_LESS);GL11.glDepthMask(true);GL11.glClearDepth(.25);GL11.glClear(GL11.GL_DEPTH_BUFFER_BIT);GL11.glDepthMask(false);GL20.glDrawBuffers(new int[]{GL30.GL_COLOR_ATTACHMENT0,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_COLOR_ATTACHMENT2});GL11.glEnable(GL11.GL_BLEND);settings(mesh,1,.5f,false,0,false);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer blocked=read(1,1);for(int i=0;i<W*W;i++)require(blocked.get(i)==1,"foreground depth bypassed");
   // Actual shared atomic pick code retains a fading door; holes/alpha0 expose background.
   for(boolean hole:new boolean[]{false,true})for(float alpha:new float[]{0,.25f,1}){
    begin();GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDisable(GL11.GL_BLEND);GL20.glDrawBuffers(new int[]{0,0,0,GL30.GL_COLOR_ATTACHMENT3});clearPicks();settings(gbuffer,1,1,false,2,true);GL20.glUniform1f(GL20.glGetUniformLocation(gbuffer,"testZ"),.4f);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);settings(gbuffer,alpha,1,hole,1,true);GL20.glUniform1f(GL20.glGetUniformLocation(gbuffer,"testZ"),-.4f);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);GL42.glMemoryBarrier(GL43.GL_SHADER_STORAGE_BARRIER_BIT|GL42.GL_BUFFER_UPDATE_BARRIER_BIT);IntBuffer result=BufferUtils.createIntBuffer(97*97);GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,picks);GL15.glGetBufferSubData(GL43.GL_SHADER_STORAGE_BUFFER,0,result);int at=48*97+48;int id=result.get(at)&255;require(id==(alpha>0&&!hole?1:2),"fading door/container pick lost id="+id+" alpha="+alpha+" hole="+hole);cases++;
   }
   // Ordinary VP keeps its original dither path when the native table is off.
   begin();GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDisable(GL11.GL_BLEND);GL20.glDrawBuffers(new int[]{0,0,0,GL30.GL_COLOR_ATTACHMENT3});settings(gbuffer,.25f,.5f,false,0,false);GL20.glUniform1i(GL20.glGetUniformLocation(gbuffer,"vpIsoObjectsOn"),0);GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer ordinary=read(3,4);int coverage=0;for(int i=0;i<W*W;i++)if(ordinary.get(i*4)>0)coverage++;require(coverage>450&&coverage<575,"ordinary VP dither changed "+coverage);require(GL11.glGetError()==0,"GL error");
   for(String path:new String[]{"shadow.frag","model_shadow.frag","vehicle_shadow.frag"}){String marker="#version 330\nvoid main(){discard;}";require(NativeObjectShaders.rewrite(path,marker).equals(marker),"shadow path changed "+path);}
   System.out.println("Fade122 GPU PASS cases="+cases+" checks="+checks+"; mesh/model true uniform0/25/50/75/100 alpha, native geometry interval, real WBOIT sum/reveal, valid cutout holes, layered tint, foreground depth, fading door/background container atomic ownership, ordinary VP dither and shadow rewrite unchanged; no game/attach/save");
  }finally{GLFW.glfwDestroyWindow(window);GLFW.glfwTerminate();}
 }
 static String fragment(String path){
  String pre="#version 330\nin vec2 vUv;in vec3 vPos,vNormal;flat in int vTexture,vGlass,vLook,vFlags;const int FLAG_BAKED_FLOOR=64;flat in vec4 vTint,vLight;uniform int hole;uniform float rawAlpha;\n#include \"lib/fade.glsl\"\n";
  if(path.equals("gbuffer.frag"))return NativeObjectShaders.rewrite(path,pre+"layout(location=3)out vec4 gColor;void main(){fadeDither();if(hole!=0&&vUv.x<=.5)discard;gColor=vec4(1);}").replace("#include \"lib/fade.glsl\"",fade);
  if(path.equals("forward.frag")){String source=pre+"#include \"lib/sample_sprite.glsl\"\n"+oit+"uniform int uDebugView;struct Surface{vec3 albedo;vec4 light;};vec4 art(){vec4 c=vec4(.3,.6,.8,rawAlpha);if(hole!=0&&vUv.x<=.5)discard;if(c.a<uAlphaRange.x||c.a>=uAlphaRange.y)discard;return c;}void main(){fadeDither();vec4 c=art();Surface s;s.albedo=c.rgb;s.light=c;vec3 color=c.rgb;float alpha=c.a;float fromEye=1;if(uDebugView==1||uDebugView==2){translucent(uDebugView == 1 ? s.albedo : s.light.rgb, c.a, fromEye);return;}translucent(color, alpha, fromEye);}";return NativeObjectShaders.rewrite(path,source).replace("#include \"lib/fade.glsl\"",fade).replace("#include \"lib/sample_sprite.glsl\"",range);}
  String stub="uniform vec2 uAlphaRange;\n"+oit+"\n#include \"lib/hsv.glsl\"\nvec4 modelArt(int textureId,vec2 uv,vec2 dx,vec2 dy,vec3 px,vec3 py,bool glass,int textureFilter){if(hole!=0&&uv.x<=.5)discard;return vec4(.6,.6,.8,rawAlpha);}void main(){fadeDither();vec3 posDx=vec3(0),posDy=vec3(0);vec2 dx=vec2(0),dy=vec2(0);vec4 c=modelArt(vTexture,vUv,dx,dy,posDx,posDy,vGlass == 1, 0);if (vGlass == 0 || c.a < uAlphaRange.x || c.a >= uAlphaRange.y) discard;vec3 colour=c.rgb;translucent(colour, c.a, length(vPos - uEye));}";
  // Keep production model gate/look/filter edits while providing deterministic material inputs.
  String modelPre="#version 330\nin vec2 vUv;in vec3 vPos,vNormal;flat in int vTexture,vGlass;flat in vec4 vTint,vLight;uniform vec3 uEye;uniform int hole;uniform float rawAlpha;\n#include \"lib/fade.glsl\"\n";
  return NativeObjectShaders.rewrite(path,modelPre+stub).replace("#include \"lib/fade.glsl\"",fade).replace("#include \"lib/hsv.glsl\"","").replace("#include \"lib/look.glsl\"","vec4 look(int key,vec2 uv,vec4 c){return vec4(c.r*.5,c.g,c.b,c.a);}");
 }
 static int program(String fragment){String vertex="#version 430\nout vec2 vUv;out vec3 vPos,vNormal;flat out int vTexture,vGlass,vLook,vFlags;flat out vec4 vTint,vLight;flat out vec3 vpIsoObjectInfo;flat out vec2 vFade;uniform float sourceAlpha,geometryAlpha,testZ;uniform vec2 interval;uniform int objectId,testFlags;void main(){vUv=vec2((gl_VertexID<<1)&2,gl_VertexID&2);gl_Position=vec4(vUv*2-1,testZ,1);vPos=vec3(0,0,1);vNormal=vec3(0,1,0);vFlags=testFlags;vTexture=0;vGlass=0;vLook=1;vTint=vLight=vec4(1);vpIsoObjectInfo=vec3(sourceAlpha,float(objectId),1);vFade=interval*vec2(1,geometryAlpha);}";int v=shader(GL20.GL_VERTEX_SHADER,vertex),f=shader(GL20.GL_FRAGMENT_SHADER,fragment),p=GL20.glCreateProgram();GL20.glAttachShader(p,v);GL20.glAttachShader(p,f);GL20.glLinkProgram(p);require(GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)!=0,GL20.glGetProgramInfoLog(p));return p;}
 static int shader(int type,String source){int s=GL20.glCreateShader(type);GL20.glShaderSource(s,source);GL20.glCompileShader(s);require(GL20.glGetShaderi(s,GL20.GL_COMPILE_STATUS)!=0,GL20.glGetShaderInfoLog(s));return s;}
 static void settings(int p,float alpha,float geometry,boolean hole,int id,boolean pick){GL20.glUseProgram(p);GL20.glUniform1f(GL20.glGetUniformLocation(p,"sourceAlpha"),alpha);GL20.glUniform1f(GL20.glGetUniformLocation(p,"geometryAlpha"),geometry);GL20.glUniform2f(GL20.glGetUniformLocation(p,"interval"),0,1);GL20.glUniform1f(GL20.glGetUniformLocation(p,"testZ"),0);GL20.glUniform1f(GL20.glGetUniformLocation(p,"rawAlpha"),1);GL20.glUniform1i(GL20.glGetUniformLocation(p,"testFlags"),0);GL20.glUniform1i(GL20.glGetUniformLocation(p,"hole"),hole?1:0);GL20.glUniform1i(GL20.glGetUniformLocation(p,"objectId"),id);GL20.glUniform1i(GL20.glGetUniformLocation(p,"vpIsoObjectsOn"),1);GL20.glUniform1i(GL20.glGetUniformLocation(p,"vpIsoPickOn"),pick?1:0);GL20.glUniform1i(GL20.glGetUniformLocation(p,"vpIsoPickBits"),8);GL20.glUniform2f(GL20.glGetUniformLocation(p,"vpIsoPickPixel"),W/2f,W/2f);GL20.glUniform2f(GL20.glGetUniformLocation(p,"vpIsoPickScale"),1,1);GL20.glUniform2f(GL20.glGetUniformLocation(p,"uAlphaRange"),.04f,.85f);}
 static void setup(){fbo=GL30.glGenFramebuffers();GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,fbo);sum=tex(GL30.GL_RGBA32F,GL11.GL_RGBA,0);reveal=tex(GL30.GL_R32F,GL11.GL_RED,1);distance=tex(GL30.GL_RG32F,GL30.GL_RG,2);opaque=tex(GL30.GL_RGBA32F,GL11.GL_RGBA,3);depth=tex(GL30.GL_DEPTH_COMPONENT32F,GL11.GL_DEPTH_COMPONENT,-1);require(GL30.glCheckFramebufferStatus(GL30.GL_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE,"FBO");GL11.glViewport(0,0,W,W);picks=GL15.glGenBuffers();GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,picks);GL15.glBufferData(GL43.GL_SHADER_STORAGE_BUFFER,97*97*4L,GL15.GL_DYNAMIC_DRAW);GL30.glBindBufferBase(GL43.GL_SHADER_STORAGE_BUFFER,6,picks);}
 static int tex(int internal,int format,int slot){int t=GL11.glGenTextures();GL11.glBindTexture(GL11.GL_TEXTURE_2D,t);GL11.glTexImage2D(GL11.GL_TEXTURE_2D,0,internal,W,W,0,format,GL11.GL_FLOAT,0L);GL30.glFramebufferTexture2D(GL30.GL_FRAMEBUFFER,slot<0?GL30.GL_DEPTH_ATTACHMENT:GL30.GL_COLOR_ATTACHMENT0+slot,GL11.GL_TEXTURE_2D,t,0);return t;}
 static void begin(){GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,fbo);GL20.glDrawBuffers(new int[]{GL30.GL_COLOR_ATTACHMENT0,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_COLOR_ATTACHMENT2,GL30.GL_COLOR_ATTACHMENT3});for(int i=0;i<4;i++)GL30.glClearBufferfv(GL11.GL_COLOR,i,i==1?new float[]{1,1,1,1}:new float[4]);GL11.glDepthMask(true);GL11.glClearDepth(1);GL11.glClear(GL11.GL_DEPTH_BUFFER_BIT);}
 static FloatBuffer read(int slot,int channels){GL11.glReadBuffer(GL30.GL_COLOR_ATTACHMENT0+slot);FloatBuffer b=BufferUtils.createFloatBuffer(W*W*channels);GL11.glReadPixels(0,0,W,W,channels==1?GL11.GL_RED:GL11.GL_RGBA,GL11.GL_FLOAT,b);return b;}
 static void clearPicks(){IntBuffer b=BufferUtils.createIntBuffer(97*97);for(int i=0;i<97*97;i++)b.put(-1);b.flip();GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,picks);GL15.glBufferSubData(GL43.GL_SHADER_STORAGE_BUFFER,0,b);}
}
